<?php require __DIR__.'/includes/bootstrap.php';require_permission('users.manage');if(current_user()['role']!=='super_admin'){http_response_code(403);exit('Forbidden');}verify_csrf();if($_SERVER['REQUEST_METHOD']!=='POST')redirect('users.php');$keys=['brands.manage','users.manage','settings.manage'];foreach(['admin','user'] as $role)foreach($keys as $key){$allowed=isset($_POST['perm'][$role][$key])?1:0;$s=db()->prepare('INSERT INTO permissions(role,permission_key,allowed) VALUES(?,?,?) ON DUPLICATE KEY UPDATE allowed=VALUES(allowed)');$s->execute([$role,$key,$allowed]);}audit('permissions_updated');flash('success','Role permissions updated.');redirect('users.php');